// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(bool dummy) public {
        // The reference contract, right after deployment and without initialization,
        // must report paused() == false (the default unpaused state).
        // The mutant negates the stored flag, so paused() returns true on the very same initial state.
        // The rule is universal: for ANY state, paused() must equal the stored paused flag.
        // The fuzzed boolean is not needed to decide the initial value, but keeps the test fuzz-driven.
        vm.assume(dummy == dummy); // keep fuzzer input, no restriction

        // The reference contract is unpaused by default (stored flag == false).
        // Its paused() getter must return false. The buggy version returns !false == true.
        assertTrue(c.paused() == false);
    }
}
